"""Runs the calibration against the virtual body (humanoid.py) and prints how well it did.

  .venv/bin/python -I sim/run.py

What happens for her: VRChat's calibration starts, the app measures her on the spot and freezes the
trackers, VRChat lets go — then the avatar's hips are checked against the body in a few poses.
Sitting and leaning with a side tracker: sim/sitting.py.
"""
import sys
import time
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "app"))
sys.path.insert(0, str(Path(__file__).resolve().parent))
import numpy as np

from fbtcal import body as B
from fbtcal import main as M
from humanoid import Body, mat_q, q_mat, rot_y

M.play = lambda *_: None
M.log = lambda *_: None


class FakeShm:
    def write_slots(self, slots):
        self.slots = slots


def make_calibrator():
    c = M.Calibrator.__new__(M.Calibrator)
    c.shm = FakeShm()
    c.cal, c.eye, c.override, c.vrc_eye, c.world_fix = {}, None, None, None, {}
    c.waist_rec, c.note, c.monado_on, c.last_head = None, ("", 0.0), True, None
    c.settings = {"voice": False, "stance_cm": 12, "tpose": True, "hip_step": False}
    M.CAL_FILE = Path("/tmp/fbtcal-sim-cal.json")
    M.SETTINGS_FILE = Path("/tmp/fbtcal-sim-settings.json")
    M.SETTINGS_FILE.unlink(missing_ok=True)
    c.last_real = {}
    c.facing_in_head = (1.0, 0.0)
    M.CONFIG = Path("/tmp/fbtcal-sim-config")
    M.CONFIG.mkdir(exist_ok=True)
    return c


def run_auto(name, body, st0, stance=12, verbose=True, vrc_eye=None, mount=None):
    """VRChat's own calibration with nothing calibrated before: the app measures her at the press."""
    cal = make_calibrator()
    cal.settings["stance_cm"] = stance
    cal.settings["waist_mount"] = mount or "auto"
    cal.monado_on, cal.vr, cal.override, cal.vrc_eye = True, None, None, vrc_eye
    cal.std_from_raw, cal.world_fix = (np.zeros(3), np.array([1.0, 0, 0, 0])), {}
    cal.last_hold_voice = 0.0
    head = body.head(st0)
    cal.last_head = head
    trk = body.trackers(st0)
    cal.last_real = {s: trk[k] for s, k in (("W", "waist"), ("L", "left_foot"), ("R", "right_foot"))}
    r, eye = st0["R_pelvis"], st0["eyes"]
    cal.last_hands = tuple((eye + r @ np.array([sg * 0.75, -0.15, 0]), np.array([1.0, 0, 0, 0])) for sg in (-1, 1))
    M.SETTINGS_FILE.unlink(missing_ok=True)  # start_override re-reads the settings file
    cal.start_override("VRChat calibration")
    if not cal.override:
        print(f"{name:<34} NOT calibrated")
        return None
    jumps = {}
    for s, role in (("W", "waist"), ("L", "left_foot"), ("R", "right_foot")):
        follow = B.compose(cal.last_real[s], cal.cal[s]["off"])
        jumps[role] = float(np.linalg.norm(follow[0] - cal.override[s][0])) * 100
    # the avatar's hips follow the body afterwards (same check as run_one)
    fhead = head
    final_T = B.compose(cal.last_real["W"], cal.cal["W"]["off"])
    fwd, _ = B.head_frame(fhead)
    avatar_hips_T = (fhead[0] - np.array([0, 0.62, 0]) - 0.075 * np.array([fwd[0], 0, fwd[2]]), final_T[1])
    off_vrc = B.compose(B.inverse(final_T), avatar_hips_T)
    worst = 0.0
    for stt in (body.pose(), body.pose(yaw=np.radians(25)), body.pose(pitch=np.radians(-6)), body.pose(pitch=np.radians(30))):
        real = body.trackers(stt)["waist"]
        avatar = B.compose(B.compose(real, cal.cal["W"]["off"]), off_vrc)
        c_pel = B.compose((stt["pelvis"], mat_q(stt["R_pelvis"])),
                          B.compose(B.inverse((st0["pelvis"], mat_q(st0["R_pelvis"]))), avatar_hips_T))
        worst = max(worst, float(np.linalg.norm(avatar[0] - c_pel[0])) * 100)
    if verbose:
        print(f"{name:<34} eye {cal.eye:.3f} (real {eye[1]:.3f})  stance {stance:>2} cm  jump at unfreeze "
              + "  ".join(f"{k} {v:4.2f}" for k, v in jumps.items()) + f" cm   avatar hips off by {worst:.1f} cm")
    return {"jumps": jumps, "worst": worst, "eye": cal.eye}


def main():
    print("VRChat calibration pressed, nothing calibrated before (heights, bodies, stances, head turned off the body):")
    for eye in (1.45, 1.56, 1.70, 1.85):
        for bname, kw in (("belt right side", dict(waist_mount=(0.16, 0.05, -0.02))),
                          ("pelvis 6 cm behind neck", dict(pelvis_behind_neck=0.06, waist_mount=(0.15, 0.05, 0.05)))):
            body = Body(eye=eye, seed=7, **kw)
            run_auto(f"{bname} / {int(eye * 100)} cm", body, body.pose(head_yaw=np.radians(8)), stance=int(12 + (eye - 1.45) * 20))
    print("\nWaist tracker place set in the settings (all 8 spots on the belt, 150 and 180 cm):")
    for eye in (1.50, 1.80):
        k = eye / 1.56
        for mount, ang in B.MOUNTS.items():
            a = np.radians(ang)
            place = (0.16 * k * np.sin(a), 0.05, -0.11 * k * np.cos(a))
            body = Body(eye=eye, seed=9, waist_mount=place)
            run_auto(f"{mount:<11} / {int(eye * 100)} cm", body, body.pose(head_yaw=np.radians(6)), mount=mount)


if __name__ == "__main__":
    main()
